def backfill_qa_sessions(apps, schema_editor):
    """把旧 QARecord 按 (course, student, catalog, session 字符串) 归组为 QASession。

    - session 字符串非空的记录归组建会话（legacy_key=原字符串，title=首问 30 字）；
    - 逐组回填 session_ref 与按 id 升序的 turn_index；
    - session 为空的旧记录不建会话（保持 legacy 只读展示，不参与多轮历史）。
    """
    QASession = apps.get_model("knowledge", "QASession")
    QARecord = apps.get_model("knowledge", "QARecord")
    db = schema_editor.connection.alias
    groups = (
        QARecord.objects.using(db)
        .exclude(session="")
        .values("course_id", "student_id", "catalog_id", "session")
        .annotate(first_id=Min("id"))
        .order_by("first_id")
    )
    for g in groups:
        records = (
            QARecord.objects.using(db)
            .filter(
                course_id=g["course_id"],
                student_id=g["student_id"],
                catalog_id=g["catalog_id"],
                session=g["session"],
            )
            .order_by("id")
        )
        first_q = records.values_list("question", flat=True).first() or ""
        sess = QASession.objects.using(db).create(
            course_id=g["course_id"],
            catalog_id=g["catalog_id"],
            student_id=g["student_id"],
            legacy_key=g["session"],
            title=first_q[:30],
        )
        turn = 0
        batch = []
        for rec in records.iterator(chunk_size=500):
            turn += 1
            rec.session_ref_id = sess.id
            rec.turn_index = turn
            batch.append(rec)
            if len(batch) >= 500:
                QARecord.objects.using(db).bulk_update(batch, ["session_ref_id", "turn_index"])
                batch = []
        if batch:
            QARecord.objects.using(db).bulk_update(batch, ["session_ref_id", "turn_index"])


